    W = draw(st.integers(1, 5))
    cand = draw(st.lists(
        st.tuples(st.integers(1, H), st.integers(1, W), st.integers(1, W)),
        min_size=1, max_size=8))
    occ = set()
    bars = []
    for r, c, l in cand:
        if c + l - 1 > W:
            l = W - c + 1
        cells = {(r, c + j) for j in range(l)}
        if cells & occ:
            continue
        occ |= cells
        bars.append((r, c, l))
